REPO='edburns/edburns-dd-3069621-cargotracker-linux-x64'; TASK=4; BASE='experiment/shepherd-control'; PR=9; VALIDATED='e8780ad6d33b189588225d6032f0d78acb441252'; BRANCH='copilot/implement-deadline-editor-backing-model'; OWNER=${REPO%%/*}; NAME=${REPO#*/}
PRJ=$(gh api "/repos/$REPO/pulls/$PR")
STATE=$(jq -r '.state' <<<"$PRJ"); DRAFT=$(jq -r '.draft' <<<"$PRJ"); PRBASE=$(jq -r '.base.ref' <<<"$PRJ"); HEAD=$(jq -r '.head.sha' <<<"$PRJ"); BASE_SHA=$(jq -r '.base.sha' <<<"$PRJ"); CHANGED=$(jq -r '.changed_files' <<<"$PRJ")
[ "$STATE" = open ] && [ "$DRAFT" = true ] && [ "$PRBASE" = "$BASE" ] && [ "$HEAD" = "$VALIDATED" ] || { echo "ERROR state invariant: state=$STATE draft=$DRAFT base=$PRBASE head=$HEAD" >&2; exit 1; }
TIMELINE=$(gh api "/repos/$REPO/issues/$PR/timeline?per_page=100" --paginate -H 'Accept: application/vnd.github+json')
START=$(jq -r '[.[] | select(.event=="copilot_work_started") | .created_at] | max // empty' <<<"$TIMELINE"); FINISH=$(jq -r '[.[] | select(.event=="copilot_work_finished") | .created_at] | max // empty' <<<"$TIMELINE")
[ -n "$START" ] && [ -n "$FINISH" ] && [[ "$FINISH" > "$START" || "$FINISH" == "$START" ]] || { echo 'ERROR lifecycle invariant' >&2; exit 1; }
FILES=$(gh api "/repos/$REPO/pulls/$PR/files?per_page=100" --paginate --jq '.[].filename'); FILE_COUNT=$(printf '%s\n' "$FILES" | sed '/^$/d' | wc -l | tr -d ' ')
BASE_TREE=$(gh api "/repos/$REPO/git/commits/$BASE_SHA" --jq '.tree.sha'); HEAD_TREE=$(gh api "/repos/$REPO/git/commits/$HEAD" --jq '.tree.sha')
[ "$CHANGED" -gt 0 ] && [ "$FILE_COUNT" -gt 0 ] && [ "$BASE_TREE" != "$HEAD_TREE" ] || { echo 'ERROR effective diff invariant' >&2; exit 1; }
GQL=$(gh api graphql --paginate -f query='query($owner:String!,$name:String!,$number:Int!,$endCursor:String){repository(owner:$owner,name:$name){pullRequest(number:$number){reviewDecision closingIssuesReferences(first:100){nodes{number}} reviewThreads(first:100,after:$endCursor){nodes{isResolved comments(last:1){nodes{author{login} body url}}}pageInfo{hasNextPage endCursor}}}}}' -F owner="$OWNER" -F name="$NAME" -F number="$PR")
LINKED=$(jq -s --argjson issue "$TASK" '[.[].data.repository.pullRequest.closingIssuesReferences.nodes[] | select(.number==$issue)] | length' <<<"$GQL"); UNRESOLVED=$(jq -s '[.[].data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false)] | length' <<<"$GQL"); DECISION=$(jq -sr '[.[].data.repository.pullRequest.reviewDecision // empty] | last // empty' <<<"$GQL")
[ "$LINKED" -eq 1 ] && [ "$UNRESOLVED" -eq 0 ] && [ "$DECISION" != CHANGES_REQUESTED ] || { echo "ERROR review/link invariant linked=$LINKED unresolved=$UNRESOLVED decision=$DECISION" >&2; exit 1; }
CHECKS=$(gh api "/repos/$REPO/commits/$HEAD/check-runs?per_page=100"); PENDING=$(jq '[.check_runs[]|select(.status!="completed")]|length' <<<"$CHECKS"); FAILING=$(jq '[.check_runs[]|select(.status=="completed")|select(.conclusion!="success" and .conclusion!="skipped" and .conclusion!="neutral")|select(.name!="No remove-before-merge directories")]|length' <<<"$CHECKS"); SUCCESS=$(jq '[.check_runs[]|select(.status=="completed" and .conclusion=="success")]|length' <<<"$CHECKS")
[ "$PENDING" -eq 0 ] && [ "$FAILING" -eq 0 ] && [ "$SUCCESS" -gt 0 ] || { echo "ERROR checks invariant pending=$PENDING failing=$FAILING success=$SUCCESS" >&2; exit 1; }
ACTION_REQUIRED=$(gh run list -R "$REPO" --branch "$BRANCH" --limit 100 --json headSha,status,conclusion --jq "[.[]|select(.headSha==\"$HEAD\")|select(.status!=\"completed\" or .conclusion==\"action_required\")]|length")
[ "$ACTION_REQUIRED" -eq 0 ] || { echo 'ERROR workflow pending/action_required' >&2; exit 1; }
LOCAL_HEAD=$(git -C '/home/edburns/.copilot/session-state/d2e67dd3-e1d9-4f0d-92a7-698677262590/files/pr9-worktree' rev-parse HEAD); [ "$LOCAL_HEAD" = "$HEAD" ] || exit 1
FINAL_HEAD=$(gh pr view "$PR" -R "$REPO" --json headRefOid --jq '.headRefOid'); [ "$FINAL_HEAD" = "$VALIDATED" ] || { echo 'ERROR head changed during validation' >&2; exit 1; }
printf 'STATE=%s\nDRAFT=%s\nBASE=%s\nHEAD=%s\nCCA_START=%s\nCCA_FINISH=%s\nCHANGED_FILES=%s\nFILE_COUNT=%s\nLINKED_TASK=%s\nUNRESOLVED_THREADS=%s\nREVIEW_DECISION=%s\nPENDING_CHECKS=%s\nFAILING_CHECKS=%s\nSUCCESSFUL_CHECKS=%s\nACTION_REQUIRED_OR_PENDING_RUNS=%s\nFILES=\n%s\n' "$STATE" "$DRAFT" "$PRBASE" "$HEAD" "$START" "$FINISH" "$CHANGED" "$FILE_COUNT" "$LINKED" "$UNRESOLVED" "${DECISION:-none}" "$PENDING" "$FAILING" "$SUCCESS" "$ACTION_REQUIRED" "$FILES"","description":"Run atomic final readiness gate","initial_wait":600,"mode":"sync"}
